using System.Drawing;
using System.Windows.Forms;
using System.Windows.Forms.Design;

public class MyControl : UserControl
{
    public string DisplayName { get; set; }
    public int MaxItems { get; set; }

    // .NET 9 breaking change: StatusStrip now defaults to
    // ToolStripSystemRenderer instead of ToolStripProfessionalRenderer.
    // Explicitly set the renderer to preserve the .NET 8 appearance.
    public static StatusStrip CreateStatusStrip()
    {
        var strip = new StatusStrip();
        strip.RenderMode = ToolStripRenderMode.Professional;
        return strip;
    }

    // .NET 9 breaking change: DropDownControl now throws
    // ArgumentNullException when passed null. Guard against it.
    public static void SafeDropDownControl(
        IWindowsFormsEditorService editorService, Control control)
    {
        if (control is not null)
        {
            editorService.DropDownControl(control);
        }
    }
}

